body {
  background: linear-gradient(160deg, #e8f4fd 0%, #dbeafe 40%, #eff6ff 100%) !important;
}

body::before {
  content: '';
  display: block;
  width: 160px;
  height: 80px;
  margin: 20px auto 10px;
  background: url("https://cdn.prod.website-files.com/6719e3902a71ea8154ba371d/6996a2c470a01e3f32ffa080_M30.png") center/contain no-repeat;
  filter: brightness(0) saturate(100%) invert(17%) sepia(80%) saturate(1200%) hue-rotate(210deg) brightness(90%);
}

/* Back to Home button - sits naturally top-left outside the card */
p:has(a[href*="github.io"]) {
  position: absolute !important;
  top: 16px !important;
  left: 16px !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  text-align: left !important;
  width: auto !important;
  z-index: 100 !important;
}

p a[href*="github.io"] {
  display: inline-flex !important;
  align-items: center !important;
  gap: 8px !important;
  padding: 10px 20px !important;
  background: #2563eb !important;
  color: #ffffff !important;
  text-decoration: none !important;
  border-radius: 10px !important;
  font-size: 14px !important;
  font-weight: 700 !important;
  box-shadow: 0 4px 16px rgba(37,99,235,0.25) !important;
  white-space: nowrap !important;
}

p a[href*="github.io"]:hover {
  background: #1d4ed8 !important;
}

/* Make sure body has relative positioning so absolute works */
body {
  position: relative !important;
}

