function cleanLiteral(value){return String(value||'').trim().replace(/^'+/,'');}
function normalize(value){return String(value||'').toLowerCase().trim().replace(/[^a-z0-9@]+/g,' ').replace(/\s+/g,' ').trim();}
function truthy(value){return !/^(false|0|no|inactive)$/i.test(String(value==null?'true':value).trim());}
function cleanAttendees(value,organisation){const blocked=normalize(organisation);const seen=new Set();return String(value||'').split(/\r?\n|;|,/).map(v=>v.trim()).filter(v=>{const k=normalize(v);if(!k||k===blocked||seen.has(k))return false;seen.add(k);return true;}).join(', ');}
function phoneDisplay(value){const phone=cleanLiteral(value);return /^#ERROR!/i.test(phone)?'Invalid contact number in Google Sheets':phone;}
function supportedUrl(url){return /^https:\/\/(?:drive|docs|sheets|slides)\.google\.com\//i.test(String(url||'').trim());}
function parseDocuments(value){const raw=cleanLiteral(value);if(!raw)return[];try{const parsed=JSON.parse(raw);if(Array.isArray(parsed))return parsed.map((entry,index)=>({name:String(entry?.name||`Document ${index+1}`),url:String(entry?.url||''),source:entry?.source==='calendar'?'calendar':'uploaded'})).filter(entry=>supportedUrl(entry.url));}catch(error){}return raw.split(/\r?\n/).map((line,index)=>{const parts=line.split('|').map(part=>part.trim());if(parts.length>=3){const url=parts.slice(2).join('|');return supportedUrl(url)?{source:/^calendar$/i.test(parts[0])?'calendar':'uploaded',name:parts[1]||`Document ${index+1}`,url}:null;}if(parts.length===2&&supportedUrl(parts[1]))return{name:parts[0]||`Document ${index+1}`,url:parts[1],source:'uploaded'};return null;}).filter(Boolean);}
const actionRows=items.map(item=>item.json||{}).filter(row=>row['Record ID']&&row['Action Item ID']);
const actionsByRecord=new Map();
actionRows.forEach(row=>{const recordId=cleanLiteral(row['Record ID']);if(!recordId)return;const list=actionsByRecord.get(recordId)||[];list.push({actionItemId:cleanLiteral(row['Action Item ID']),recordId,action:cleanLiteral(row['Action']),owner:cleanLiteral(row['Owner']),dueDate:cleanLiteral(row['Due Date']),status:['Open','In Progress','Completed'].includes(cleanLiteral(row['Status']))?cleanLiteral(row['Status']):'Open',isActive:truthy(row['Is Active']),createdBy:cleanLiteral(row['Created By']),createdAt:cleanLiteral(row['Created At']),updatedBy:cleanLiteral(row['Updated By']),updatedAt:cleanLiteral(row['Updated At'])});actionsByRecord.set(recordId,list);});
const mainRows=$('Read All CRM Records1').all().map(item=>item.json||{});
const records=mainRows.map((row,index)=>{const recordId=cleanLiteral(row['Record ID']);const structured=(actionsByRecord.get(recordId)||[]).filter(item=>item.isActive);const documentsRaw=cleanLiteral(row['Meeting Documents']||row['Meeting Document']||'');const companyName=row['Company Name']||'';return{id:index,recordId,recordStatus:cleanLiteral(row['Record Status']||'Active')||'Active',personName:row['Person Name']||'',companyName,email:row['Email']||'',phone:phoneDisplay(row['Contact Number']||''),jobTitle:row['Job Title']||'',meetingTitle:row['Calendar Event']||'',meetingDate:row['Meeting Date']||'',timeUploaded:row['Time Uploaded']||'',createdAt:row['Time Uploaded']||'',attendees:cleanAttendees(row['Attendees']||'',companyName),uploaderName:row['Uploader Name']||'',uploaderEmail:row['Uploader Email']||'',reason:row['Reason']||'',meetingNotes:row['Meeting notes']||'',actionItems:structured.length?structured:(row['Action Items']||''),meetingDocumentsRaw:documentsRaw,meetingDocuments:parseDocuments(documentsRaw),lastUpdated:row['Last Updated']||'',updatedBy:row['Updated By']||'',searchIndex:row['Search Index']||row['Search index']||''};});
return[{json:{success:true,count:records.length,records}}];

const b = $json.body || {};

function buildManualDateTime(dateOnly, timeOnly) {
  const d = String(dateOnly || '').trim();
  const t = String(timeOnly || '').trim();
  if (d && t) return d + 'T' + t + ':00+08:00';
  if (d) return d;
  return '';
}

function formatMeetingDate(value) {
  if (!value) return '';

  const raw = String(value).trim();

  if (/^[A-Za-z]{3},\s\d{1,2}\s[A-Za-z]{3}\s\d{4}/.test(raw)) {
    return raw;
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
    const d = new Date(raw + 'T00:00:00+08:00');
    const parts = new Intl.DateTimeFormat('en-GB', {
      timeZone: 'Asia/Kuala_Lumpur',
      weekday: 'short',
      day: 'numeric',
      month: 'short',
      year: 'numeric'
    }).formatToParts(d);
    const get = (type) => parts.find(p => p.type === type)?.value || '';
    return `${get('weekday')}, ${get('day')} ${get('month')} ${get('year')}`;
  }

  const d = new Date(raw);
  if (isNaN(d.getTime())) return raw;

  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Kuala_Lumpur',
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true
  }).formatToParts(d);

  const get = (type) => parts.find(p => p.type === type)?.value || '';
  return `${get('weekday')}, ${get('day')} ${get('month')} ${get('year')}, ${get('hour')}:${get('minute')} ${get('dayPeriod').toUpperCase()}`;
}

function documentKeys(binary) {
  return Object.keys(binary || {})
    .filter(key => key === 'meetingDocument' || /^meetingDocument_\d+$/i.test(key))
    .sort((a, b) => {
      const ai = Number((a.match(/(\d+)$/) || [0, 0])[1]);
      const bi = Number((b.match(/(\d+)$/) || [0, 0])[1]);
      return ai - bi;
    })
    .slice(0, 5);
}

const binary = $binary || {};
const pdfKeys = documentKeys(binary);

function parseCalendarAttachments(value) {
  let parsed = value;
  if (typeof parsed === 'string') {
    try { parsed = JSON.parse(parsed); } catch (e) { parsed = []; }
  }
  return (Array.isArray(parsed) ? parsed : [])
    .map((entry, index) => {
      const name = String(entry?.name || entry?.title || `Calendar attachment ${index + 1}`).trim();
      const url = String(entry?.url || entry?.fileUrl || '').trim();
      const mimeType = String(entry?.mimeType || '').trim();
      if (!/^https:\/\//i.test(url)) return null;
      return { name, url, mimeType, source: 'calendar' };
    })
    .filter(Boolean);
}

function documentLine(document) {
  const label = document.source === 'calendar' ? 'Calendar' : 'Uploaded';
  return `${label} | ${document.name} | ${document.url}`;
}


function parseReviewedContacts(value) {
  let parsed = value;
  if (typeof parsed === 'string') {
    try { parsed = JSON.parse(parsed); } catch (e) { parsed = []; }
  }
  return (Array.isArray(parsed) ? parsed : [])
    .slice(0, 10)
    .map((entry, index) => ({
      cardNumber: Number(entry?.cardNumber || index + 1),
      personName: String(entry?.personName || entry?.name || '').trim(),
      companyName: String(entry?.companyName || entry?.company || '').trim(),
      email: String(entry?.email || entry?.emailAddress || '').trim(),
      contactNumber: String(entry?.contactNumber || entry?.phone || entry?.mobile || '').trim(),
      jobTitle: String(entry?.jobTitle || entry?.designation || '').trim(),
      confidence: String(entry?.confidence || 'unknown').trim(),
      reviewReasons: Array.isArray(entry?.reviewReasons) ? entry.reviewReasons.map(value => String(value || '').trim()).filter(Boolean) : []
    }));
}


function normalizeKey(value) {
  return String(value || '').toLowerCase().trim().replace(/[^a-z0-9@]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function cleanAttendees(value, organisations = []) {
  const blocked = new Set((Array.isArray(organisations) ? organisations : [organisations]).map(normalizeKey).filter(Boolean));
  const seen = new Set();
  return String(value || '').split(/\r?\n|;|,/).map(v => v.trim()).filter(v => {
    const key = normalizeKey(v);
    if (!key || blocked.has(key) || seen.has(key)) return false;
    seen.add(key);
    return true;
  }).join(', ');
}
function actionStatus(value) {
  const key = normalizeKey(value);
  if (/(completed|complete|done|closed|resolved)/.test(key)) return 'Completed';
  if (/(in progress|progress|ongoing|underway|started)/.test(key)) return 'In Progress';
  return 'Open';
}
function legacyActionFragments(value) {
  const raw = String(value || '').replace(/\r/g, '').trim();
  if (!raw) return [];
  const parts = [];
  raw.split(/\n+/).forEach(line => {
    const split = line.replace(/(^|\s+)(?=\d{1,2}[.)]\s+)/g, '\n').replace(/(^|\s+)(?=[•*-]\s+)/g, '\n').split(/\n+/);
    split.forEach(part => {
      const clean = part.replace(/^\s*(?:\d{1,2}[.)]|[•*-])\s*/, '').trim();
      if (clean) parts.push(clean);
    });
  });
  return [...new Map(parts.map(v => [normalizeKey(v), v])).values()];
}
function parseActionItems(value) {
  let parsed = value;
  if (typeof parsed === 'string') {
    try { parsed = JSON.parse(parsed); } catch (error) { parsed = legacyActionFragments(parsed).map(action => ({ action })); }
  }
  if (!Array.isArray(parsed)) parsed = parsed && typeof parsed === 'object' ? [parsed] : [];
  const seen = new Set();
  return parsed.map((item, index) => {
    const action = String(item?.action || item?.text || item?.description || '').trim();
    const key = normalizeKey(action);
    if (!action || seen.has(key)) return null;
    seen.add(key);
    return {
      actionItemId: String(item?.actionItemId || item?.id || `AI-${Date.now().toString(36).toUpperCase()}-${String(index + 1).padStart(2,'0')}`).trim(),
      action, owner: String(item?.owner || item?.assignee || '').trim(), dueDate: String(item?.dueDate || item?.deadline || '').trim(),
      status: actionStatus(item?.status || 'Open'), isActive: item?.isActive !== false
    };
  }).filter(Boolean);
}

const reviewedContacts = parseReviewedContacts(b.reviewedContacts || []);
const actionItems = parseActionItems(b.actionItems || []);
const actionItemsLegacyText = actionItems.map((item, index) => `${index + 1}) ${item.action}`).join(' ');
const submittedOrganisations = reviewedContacts.map(item => item.companyName).concat([b.manualCompanyName || '']);

const calendarAttachments = parseCalendarAttachments(b.calendarAttachments || []);
const initialDocumentsCell = calendarAttachments.map(documentLine).join('\n');

return [{
  json: {
    uploaderName: b.uploaderName || '',
    uploaderEmail: b.uploaderEmail || '',
    purpose: b.purpose || '',
    meetingNotes: b.meetingNotes || '',
    actionItems,
    actionItemsLegacyText,
    eventTitle: b.eventTitle || '',
    eventDate: formatMeetingDate(b.eventDate || buildManualDateTime(b.eventDateOnly, b.eventTime) || ''),
    eventDateOnly: b.eventDateOnly || '',
    eventTime: b.eventTime || '',
    attendees: cleanAttendees(b.attendees || '', submittedOrganisations),

    inputMethod: b.inputMethod || 'businessCard',
    manualPersonName: b.manualPersonName || '',
    manualCompanyName: b.manualCompanyName || '',
    manualEmail: b.manualEmail || '',
    manualPhone: b.manualPhone || '',
    reviewedContacts,
    reviewedContactCount: reviewedContacts.length,
    contactSource: b.contactSource || '',
    submissionId: 'CRM-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2,8).toUpperCase(),

    hasMeetingDocuments: pdfKeys.length ? 'yes' : 'no',
    meetingDocumentCount: pdfKeys.length,
    meetingDocumentBinaryKeys: pdfKeys,
    meetingDocumentOriginalNames: pdfKeys.map(key => binary[key]?.fileName || 'meeting-document.pdf'),

    calendarAttachments,
    calendarAttachmentCount: calendarAttachments.length,
    meetingDocuments: calendarAttachments,
    meetingDocumentsCell: initialDocumentsCell,
    meetingDocumentsUploadedCount: 0,
    meetingDocumentsFailedCount: 0,
    meetingDocumentsFailedNames: [],

    submittedAt: new Date().toISOString()
  },
