}];

// ============================================================================
// n8n Code node: "Build Relationship Graph Page"
// Relationship Intelligence - tech motion version
// - Top navbar only.
// - No bottom KPI cards.
// - Animated relationship flow lines.
// - Graph labels use abbreviations.
// - Company full names are used in filters/details and wrapped cleanly where shown.
// - Contact nodes merge by cleaned person name + company abbreviation.
// ============================================================================

const homeUrl = "https://datamranti.github.io/mranti-crm/#dashboard";
const contactsUrl = "https://datamranti.github.io/mranti-crm/#contacts";

function value(row, key) {
  return String((row && row[key]) || '').trim();
}

const GENERIC_DOMAINS = [
  'gmail.com','gmail','yahoo.com','yahoo','hotmail.com','hotmail','outlook.com','outlook',
  'icloud.com','icloud','live.com','live','protonmail.com','protonmail','aol.com','aol',
  'ymail.com','ymail','msn.com','msn','yandex.com','yandex'
];

const KNOWN_DOMAIN_SHORTFORMS = {};

const FULLNAME_BY_SHORTFORM = {};

const BAD_SHORTFORMS = [
  'MINISTRY','EMBASSY','MALAYSIAN','MALAYSIA','SURUHANJAYA','AUTHORITY',
  'COMPANY','SDN','BHD','BERHAD','SDN BHD','THE','OF','AND','FOR','UNKNOWN',
  'GOV','COM','MY','ORG','NET','YAHOO','GMAIL','OUTLOOK','HOTMAIL','ICLOUD'
];

function upperClean(v) {
  return String(v || '').trim().replace(/\s+/g, ' ').toUpperCase();
}

function getDomain(email) {
  return String(email || '').trim().toLowerCase().split('@')[1] || '';
}

function isGenericDomain(domain) {
  const d = String(domain || '').trim().toLowerCase();
  const first = d.split('.')[0];
  return GENERIC_DOMAINS.includes(d) || GENERIC_DOMAINS.includes(first);
}

function bracketAcronym(companyName) {
  const m = String(companyName || '').match(/\(([A-Z][A-Z0-9&.-]{1,12})\)/);
  return m ? upperClean(m[1].replace(/[^A-Z0-9]/g, '')) : '';
}


function explicitAcronymWord(companyName) {
  const raw = String(companyName || '').trim();
  if (!raw) return '';

  // Only trust explicit acronym-looking words if the original company name has normal casing.
  // This prevents ALL-CAPS full company names from producing false acronyms like ECONOMY or HALL.
  const hasLowercase = /[a-z]/.test(raw);
  if (!hasLowercase) return '';

  const stop = new Set(['SDN','BHD','BERHAD','THE','OF','AND','FOR','COMPANY','CO','LTD','LIMITED','PTE','LLP','PLT','INC','CORPORATION','CORP']);
  const tokens = raw
    .replace(/[()]/g, ' ')
    .split(/\s+/)
    .map(t => t.replace(/[^A-Za-z0-9&.-]/g, ''))
    .filter(Boolean);

  for (const token of tokens) {
    const upper = token.toUpperCase().replace(/[^A-Z0-9]/g, '');
    const isOriginalUppercase = token === token.toUpperCase();
    const isAcronymLength = upper.length >= 2 && upper.length <= 6;

    if (isOriginalUppercase && isAcronymLength && !stop.has(upper) && !BAD_SHORTFORMS.includes(upper)) {
      return upper;
    }
  }

  return '';
}

function acronymFromCompanyName(companyName) {
  const explicit = explicitAcronymWord(companyName);
  if (explicit) return explicit;

  const stop = new Set(['SDN','BHD','BERHAD','THE','OF','AND','FOR','COMPANY','CO','LTD','LIMITED','PTE','LLP','PLT','INC','CORPORATION','CORP']);
  const words = upperClean(companyName)
    .replace(/\([^)]*\)/g, ' ')
    .replace(/&/g, ' AND ')
    .replace(/[^A-Z0-9 ]/g, ' ')
    .split(/\s+/)
    .filter(w => w && !stop.has(w));

  if (!words.length) return 'UNRESOLVED';

  const initials = words.map(w => w[0]).join('');
  if (initials.length >= 2 && initials.length <= 8) return initials;

  return words.slice(0, 3).map(w => w[0]).join('').slice(0, 8) || words[0].slice(0, 8);
}

function shortFromDomain(domain) {
  const d = String(domain || '').trim().toLowerCase();
  if (!d || isGenericDomain(d)) return '';

  const firstRaw = d.split('.')[0] || '';
  if (!firstRaw || isGenericDomain(firstRaw)) return '';

  // Generic only: no company-specific mapping.
  // Accept acronym-like domain tokens only.
  // This prevents long plain-word domains from becoming graph abbreviations.
  const parts = firstRaw.split(/[-_]/).filter(Boolean);

  if (parts.length >= 2) {
    const initials = parts.map(p => p[0]).join('').replace(/[^a-z0-9]/g, '').toUpperCase();
    if (initials.length >= 2 && initials.length <= 10) return initials;
  }

  const token = firstRaw.replace(/[^a-z0-9]/g, '').toUpperCase();

  // Accept compact acronym-like domains only.
  // Examples accepted generically: MIDA, MTDC, TPM, MDV, MFA, MOSTI.
  // Examples rejected generically: EKONOMI, SECURITIESCOMMISSION, MALAYSIA.
  if (/^[A-Z0-9]{2,6}$/.test(token)) return token;

  return '';
}

function validShortform(v, companyName) {
  const raw = upperClean(v);
  const s = raw.replace(/[^A-Z0-9]/g, '');
  if (!s) return '';
  if (s.length < 2 || s.length > 12) return '';
  if (BAD_SHORTFORMS.includes(s)) return '';
  if (GENERIC_DOMAINS.includes(s.toLowerCase())) return '';

  const full = upperClean(companyName).replace(/[^A-Z0-9]/g, '');
  if (full && s === full) return '';

  return s;
}

function resolveClientShort(companyName, providedShort, email) {
  // Generic resolver v4. No client-company hardcoded map.
  // Priority:
  // 1. Existing clean value, only if supplied by another resolver.
  // 2. Acronym written in brackets, e.g. Malaysian Debt Ventures (MDV).
  // 3. Short/acronym-like email domain, e.g. person@mdv.com.my -> MDV.
  // 4. Company-name initials, e.g. Ministry of Economy -> MOE, D Hall Supplies -> DHS.
  const provided = validShortform(providedShort, companyName);
  if (provided) return provided;

  const bracket = bracketAcronym(companyName);
  if (bracket) return bracket;

  const domainShort = shortFromDomain(getDomain(email));
  if (domainShort) return domainShort;

  return acronymFromCompanyName(companyName);
}

function fullCompanyName(companyName, clientFullName, shortform) {
  const explicitFull = String(clientFullName || '').trim();
  if (explicitFull && explicitFull.toUpperCase() !== String(shortform || '').toUpperCase()) return explicitFull;

  const cleaned = String(companyName || '').trim();
  if (cleaned) return cleaned.replace(/\s*\(([A-Z][A-Z0-9&.-]{1,12})\)\s*$/g, '').trim();

  return shortform || 'Unknown company';
}

function resolveUploaderShort() {
  return 'MRANTI';
}

function canonicalPersonName(name) {
  return String(name || '')
    .trim()
    .replace(/^(mr|mrs|ms|miss|madam|puan|encik|en|dr|dato|datuk|prof)\.?\s+/i, '')
    .replace(/[^a-z0-9\s']/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toUpperCase();
}

const records = items
  .map((item, index) => {
    const r = item.json || {};
    const company = value(r, 'Company Name');
    const email = value(r, 'Email');
    const clientShort = resolveClientShort(company, '', email);
    const clientFull = fullCompanyName(company, '', clientShort);

    return {
      id: index,
      company,
      companyFull: clientFull,
      person: value(r, 'Person Name'),
      email,
      phone: value(r, 'Contact Number'),
      uploader: value(r, 'Uploader Name'),
      uploaderEmail: value(r, 'Uploader Email'),
      reason: value(r, 'Reason'),
      meetingTitle: value(r, 'Calendar Event'),
      meetingDate: value(r, 'Meeting Date'),
      attendees: value(r, 'Attendees'),
      notes: value(r, 'Meeting notes'),
      timeUploaded: value(r, 'Time Uploaded'),
      searchIndex: value(r, 'Search Index'),
      actionItems: value(r, 'Action Items'),
      recordStatus: value(r, 'Record Status') || 'Active',
      uploaderShort: resolveUploaderShort(),
      clientShort
    };
  })
  .filter(r => String(r.recordStatus || 'Active').toLowerCase() !== 'archived')
  .filter(r => r.company || r.person || r.meetingTitle || r.uploader || r.attendees);

const recordsJson = JSON.stringify(records).replace(/</g, '\\u003c');

const lastUpdated = new Date().toLocaleString('en-MY', {
  timeZone: 'Asia/Kuala_Lumpur',
  day: 'numeric',
  month: 'short',
  year: 'numeric',
  hour: 'numeric',
  minute: '2-digit',
  hour12: true
});

const SHARED_STYLES = `
<style>
:root{
  --blue:#2563eb; --blue-dark:#1d4ed8; --cyan:#06b6d4; --teal:#14b8a6; --purple:#8b5cf6;
  --text:#0f172a; --muted:#64748b; --muted-2:#94a3b8; --line:#e2e8f0;
  --border:rgba(147,197,253,0.42);
  --card-bg:rgba(255,255,255,0.94);
  --shadow:0 18px 54px rgba(37,99,235,0.11), 0 2px 8px rgba(15,23,42,0.04);
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
body{
  font-family:'Inter','Segoe UI',Arial,sans-serif;
  color:var(--text);
  min-height:100vh;
  background:
    radial-gradient(circle at top left, rgba(37,99,235,0.14), transparent 28%),
    radial-gradient(circle at bottom right, rgba(0,214,255,0.14), transparent 34%),
    linear-gradient(145deg, #f8fbff 0%, #eaf3ff 46%, #f7fbff 100%);
  padding:24px;
}
.shell{ width:100%; max-width:1500px; margin:0 auto; display:flex; flex-direction:column; gap:16px; }

.top-nav{
  display:flex; align-items:center; justify-content:space-between; gap:18px;
  padding:16px 20px; border-radius:24px;
  background:rgba(255,255,255,0.88); border:1px solid var(--border);
  box-shadow:var(--shadow); backdrop-filter:blur(16px);
}
.brand-block{ display:flex; align-items:center; gap:16px; min-width:0; }
.brand-logo{ width:150px; height:46px; flex-shrink:0;
  background:url("https://cdn.prod.website-files.com/6719e3902a71ea8154ba371d/6996a2c470a01e3f32ffa080_M30.png") center/contain no-repeat;
  filter:brightness(0) saturate(100%) invert(17%) sepia(80%) saturate(1200%) hue-rotate(210deg) brightness(90%);
}
.brand-divider{ width:1px; height:34px; background:rgba(148,163,184,0.35); flex-shrink:0; }
.brand-kicker{ font-size:11px; font-weight:800; letter-spacing:1.8px; text-transform:uppercase; color:var(--blue); line-height:1; }
.brand-subtitle{ margin-top:5px; font-size:12px; color:var(--muted); font-weight:650; }
.top-actions{ display:flex; align-items:center; gap:12px; flex-shrink:0; }
.nav-btn{ display:inline-flex; align-items:center; padding:10px 18px; background:#fff; color:var(--blue); text-decoration:none; border-radius:12px; font-size:12px; font-weight:800; border:1.5px solid rgba(147,197,253,0.65); transition:all .2s ease; white-space:nowrap; }
.nav-btn:hover{ border-color:var(--blue); background:rgba(239,246,255,0.9); }
.back-btn{ display:inline-flex; align-items:center; padding:11px 20px; background:var(--blue); color:#fff; text-decoration:none; border-radius:12px; font-size:12px; font-weight:800; box-shadow:0 10px 24px rgba(37,99,235,0.22); transition:all .2s ease; white-space:nowrap; }
.back-btn:hover{ background:var(--blue-dark); transform:translateY(-1px); }

.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;flex-wrap:wrap;}
.page-title{font-size:28px;font-weight:850;letter-spacing:-0.9px;color:var(--text);line-height:1.08;}
.page-subtitle{margin-top:5px;font-size:13px;color:#475569;font-weight:600;}
.update-text{font-size:11.5px;color:#475569;font-weight:700;}

.filter-row{
  display:grid;
  grid-template-columns:minmax(260px, 1.3fr) minmax(240px, 1fr) minmax(220px, .9fr) auto;
  gap:12px;
  align-items:end;
}
.filter-card{
  background:rgba(255,255,255,0.9);
  border:1px solid var(--border);
  box-shadow:0 10px 34px rgba(37,99,235,0.08);
  border-radius:16px;
  padding:9px 12px;
}
.filter-label{font-size:10px;font-weight:750;color:#64748b;margin-bottom:4px;}
.search-wrap{display:flex;align-items:center;gap:8px;}
.search-input,.select-input{
  width:100%;border:none;outline:none;background:transparent;
  color:var(--text);font-family:inherit;font-size:13px;font-weight:750;
}
.search-input::placeholder{color:#94a3b8;}
.filter-icon{font-size:16px;color:var(--muted);}
.reset-top{
  height:48px;padding:0 18px;border-radius:14px;border:1.5px solid rgba(147,197,253,0.65);
  background:#fff;color:var(--blue);font-family:inherit;font-size:12px;font-weight:850;cursor:pointer;
}
.reset-top:hover{background:#eff6ff;border-color:var(--blue);}

.legend-bar{
  display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;
  padding:4px 2px 0;
}
.legend-left{display:flex;align-items:center;gap:22px;flex-wrap:wrap;}
.legend-chip{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:800;color:#334155;}
.dot{width:12px;height:12px;border-radius:999px;display:inline-block;box-shadow:0 0 9px currentColor;}
.dot-company-main{background:#174eea;color:#174eea;}
.dot-staff{background:#60a5fa;color:#60a5fa;}
.dot-contact{background:#a855f7;color:#a855f7;}
.dot-company-ext{background:#2dd4bf;color:#2dd4bf;}
.relationship-count{font-size:12px;font-weight:800;color:#1e293b;}

.main-workspace{
  display:grid;
  grid-template-columns:minmax(760px, 1fr) 360px;
  gap:16px;
  align-items:stretch;
}

.graph-panel{
  position:relative;
  min-height:780px;
  border-radius:24px;
  background:
    radial-gradient(circle at 18% 20%, rgba(37,99,235,0.18), transparent 28%),
    radial-gradient(circle at 78% 70%, rgba(20,184,166,0.18), transparent 31%),
    radial-gradient(circle at 50% 50%, rgba(139,92,246,0.08), transparent 44%),
    linear-gradient(145deg, rgba(248,251,255,.98), rgba(239,247,255,.94));
  border:1px solid var(--border);
  box-shadow:var(--shadow), inset 0 0 0 1px rgba(255,255,255,.65);
  overflow:hidden;
}
.graph-panel::before{
  content:'';
  position:absolute; inset:0; pointer-events:none; opacity:.55;
  background-image:
    linear-gradient(rgba(37,99,235,.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(37,99,235,.08) 1px, transparent 1px);
  background-size:38px 38px;
  mask-image:radial-gradient(circle at 50% 52%, #000 0%, rgba(0,0,0,.8) 52%, transparent 100%);
}
.graph-panel::after{
  content:'';
  position:absolute; inset:-40%; pointer-events:none; opacity:.22;
  background:conic-gradient(from 180deg, transparent, rgba(6,182,212,.18), transparent, rgba(37,99,235,.15), transparent);
  animation:fieldRotate 18s linear infinite;
}
@keyframes fieldRotate{to{transform:rotate(360deg);}}
@keyframes flowDash{to{stroke-dashoffset:-36;}}
@keyframes nodePulse{0%,100%{filter:drop-shadow(0 12px 18px rgba(15,23,42,.10));}50%{filter:drop-shadow(0 0 20px rgba(37,99,235,.25));}}
@keyframes glowPulse{0%,100%{opacity:.45;}50%{opacity:.95;}}
#graphSvg{position:absolute;inset:0;width:100%;height:100%;z-index:2;cursor:grab;}
#graphSvg.dragging{cursor:grabbing;}
.edge{
  stroke:#64748b;
  stroke-width:1.25;
  opacity:.62;
  fill:none;
}
.edge-flow{
  stroke:url(#flowGradient);
  stroke-width:2.2;
  opacity:.5;
  fill:none;
  stroke-dasharray:10 16;
  animation:flowDash 2.4s linear infinite;
}
.edge.strong{stroke-width:2.5;opacity:.86;}
.edge-flow.strong{stroke-width:3.4;opacity:.72;}
.edge.dashed{stroke-dasharray:6 6;}
.edge-count{
  fill:#fff;
  font-size:10px;
  font-weight:850;
  text-anchor:middle;
  dominant-baseline:middle;
  pointer-events:none;
}
.edge-count-bg{fill:#475569;rx:5;ry:5;}

.node circle{
  stroke-width:2.4;
  filter:drop-shadow(0 0 18px rgba(37,99,235,.18));
  cursor:pointer;
  animation:nodePulse 4.6s ease-in-out infinite;
}
.node text{
  fill:#0f172a;
  font-size:11px;
  font-weight:850;
  text-anchor:middle;
  paint-order:stroke;
  stroke:#fff;
  stroke-width:5px;
  stroke-linejoin:round;
  pointer-events:none;
}
.node .subtext{font-size:9px;fill:#475569;font-weight:760;}
.node.company-main circle{fill:#174eea;stroke:#dbeafe;}
.node.company-main text{fill:#fff;stroke:#174eea;stroke-width:3.5px;}
.node.staff circle{fill:#eaf4ff;stroke:#60a5fa;}
.node.contact circle{fill:#f3e8ff;stroke:#a855f7;}
.node.company-ext circle{fill:#ecfdf5;stroke:#2dd4bf;}
.node.selected circle{stroke:#facc15;stroke-width:4;filter:drop-shadow(0 0 24px rgba(250,204,21,.45));}

.zoom-tools{
  position:absolute;left:18px;top:58px;z-index:5;
  display:flex;flex-direction:column;gap:8px;
  padding:8px;background:rgba(255,255,255,0.9);border:1px solid rgba(226,232,240,.9);
  border-radius:14px;box-shadow:0 12px 28px rgba(15,23,42,.10);
}
.zoom-btn{
  width:30px;height:30px;border:none;background:#fff;border-radius:9px;
  font-size:17px;font-weight:850;color:#0f172a;cursor:pointer;
}
.zoom-btn:hover{background:#eff6ff;color:var(--blue);}
.mini-map{
  position:absolute;left:20px;bottom:20px;width:160px;height:120px;z-index:5;
  background:rgba(255,255,255,0.78);border:1px solid rgba(226,232,240,.95);
  border-radius:14px;box-shadow:0 12px 28px rgba(15,23,42,.10);
  display:flex;align-items:center;justify-content:center;color:#94a3b8;font-size:11px;font-weight:800;
  backdrop-filter:blur(12px);
}
.mini-map::before{
  content:''; width:118px; height:78px; border:1.5px solid rgba(37,99,235,.5);
  background:
    radial-gradient(circle at 15% 50%, #2563eb 0 5px, transparent 6px),
    radial-gradient(circle at 38% 28%, #60a5fa 0 5px, transparent 6px),
    radial-gradient(circle at 55% 42%, #a855f7 0 5px, transparent 6px),
    radial-gradient(circle at 78% 50%, #2dd4bf 0 5px, transparent 6px),
    linear-gradient(90deg, transparent 0 100%);
}
.mini-map{font-size:0;}

.detail-panel{
  background:rgba(255,255,255,0.95);
  border:1px solid var(--border);
  border-radius:22px;
  box-shadow:var(--shadow);
  padding:18px;
  min-height:780px;
  display:flex;
  flex-direction:column;
  gap:14px;
}
.detail-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;}
.avatar{
  width:46px;height:46px;border-radius:16px;display:flex;align-items:center;justify-content:center;
  background:linear-gradient(135deg,#7c3aed,#a855f7);color:#fff;font-size:22px;font-weight:900;flex-shrink:0;
}
.detail-title-block{flex:1;min-width:0;}
.detail-title{font-size:17px;line-height:1.25;font-weight:850;color:#111827;}
.detail-subtitle{margin-top:3px;font-size:12px;line-height:1.35;color:#475569;font-weight:650;}
.stat-grid{display:grid;grid-template-columns:1fr 1fr;border:1px solid #e2e8f0;border-radius:14px;overflow:hidden;background:#fff;}
.stat-box{padding:13px 12px;border-right:1px solid #e2e8f0;border-bottom:1px solid #e2e8f0;}
.stat-box:nth-child(2n){border-right:none;}
.stat-box:nth-last-child(-n+2){border-bottom:none;}
.stat-label{font-size:10px;color:#64748b;font-weight:750;margin-bottom:4px;}
.stat-value{font-size:15px;color:#0f172a;font-weight:850;}

.card-section{
  border:1px solid #e2e8f0;border-radius:14px;background:#fff;padding:13px;
}
.card-section.highlight{border-color:#ddd6fe;background:linear-gradient(135deg,#fbfaff,#fff);}
.section-kicker{font-size:11px;font-weight:850;color:#6d28d9;margin-bottom:8px;}
.section-copy{font-size:12px;line-height:1.5;color:#334155;font-weight:650;}
.chip-row{display:flex;flex-wrap:wrap;gap:6px;}
.info-chip{background:#eff6ff;color:#1e3a8a;border:1px solid #bfdbfe;font-size:10.5px;font-weight:800;padding:5px 9px;border-radius:999px;}

.history-list{display:flex;flex-direction:column;gap:10px;max-height:310px;overflow:auto;padding-right:4px;}
.history-item{border:1px solid #e2e8f0;background:#fff;border-radius:12px;padding:10px;}
.history-top{display:flex;justify-content:space-between;gap:10px;margin-bottom:4px;}
.history-date{font-size:10px;color:#64748b;font-weight:750;white-space:nowrap;}
.history-title{font-size:11.5px;color:#0f172a;font-weight:850;line-height:1.35;}
.history-meta{font-size:10.5px;color:#64748b;font-weight:650;line-height:1.35;margin-top:4px;}
.empty-state{font-size:12px;color:#64748b;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:12px;padding:12px;line-height:1.45;}

@media (max-width:1200px){
  .main-workspace{grid-template-columns:1fr;}
  .detail-panel{min-height:auto;}
}
@media (max-width:900px){
  body{padding:14px;}
  .top-nav{flex-direction:column;align-items:stretch;}
  .brand-divider,.brand-subtitle{display:none;}
  .top-actions{justify-content:space-between;}
  .filter-row{grid-template-columns:1fr;}
  .graph-panel{min-height:660px;}
}
</style>
`;

