${SCRIPT_OPEN}
(function(){
  console.log('GRAPH_SEARCH_INDEX_V13_PLACEHOLDER_RESTORED loaded');
  const records = ${recordsJson};
  const NS = 'http://www.w3.org/2000/svg';
  let graph = { nodes: [], edges: [] };
  let nodeMap = new Map();
  let selectedNodeId = '';
  let transform = { x: 0, y: 0, scale: 1 };
  let draggingNode = null;
  let draggingCanvas = false;
  let dragStart = null;
  let simulationFrame = null;
  let simulationHeat = 0;
  let simulationPaused = false;

  function clean(v){ return String(v || '').trim(); }
  function esc(v){ return String(v || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
  function key(type, value){ return type + ':' + clean(value).toLowerCase().replace(/[^a-z0-9@._-]+/g,'-').replace(/^-+|-+$/g,''); }
  function unique(vals){ return Array.from(new Set(vals.filter(Boolean))).sort((a,b)=>a.localeCompare(b)); }
  function sortByDateDesc(list){ return list.slice().sort((a,b) => new Date(b.timeUploaded||0) - new Date(a.timeUploaded||0)); }

  function normalizeSearchText(value){
    return String(value || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, ' ')
      .replace(/&/g, ' and ')
      .replace(/[^a-z0-9 ]/g, ' ')
      .replace(/ +/g, ' ')
      .trim();
  }

  function searchTokens(value){
    const normalized = normalizeSearchText(value);
    return normalized ? normalized.split(' ') : [];
  }

  function tokenPrefixMatch(query, candidate){
    const queryTokens = searchTokens(query);
    const candidateTokens = searchTokens(candidate);
    return queryTokens.length > 0 && candidateTokens.length > 0 &&
      queryTokens.every(qt => candidateTokens.some(ct => ct.startsWith(qt)));
  }

  function exactSearchMatch(query, candidate){
    const normalized = normalizeSearchText(query);
    return Boolean(normalized && normalized === normalizeSearchText(candidate));
  }

  function partialPhoneMatch(query, phone){
    const digits = String(query || '').replace(/[^0-9]/g, '');
    const phoneDigits = String(phone || '').replace(/[^0-9]/g, '');
    return digits.length >= 3 && phoneDigits.includes(digits);
  }

  function recordSearchScore(r, query){
    const clientFull = fullCompanyNameForRecord(r, 'client');
    const uploaderFull = fullCompanyNameForRecord(r, 'uploader');
    const primary = [r.person, r.company, r.companyFull, clientFull, r.clientShort, r.uploader, r.uploaderShort, uploaderFull];
    if (primary.some(value => exactSearchMatch(query, value))) return 500;
    if (primary.some(value => tokenPrefixMatch(query, value))) return 400;
    if ([r.email, r.uploaderEmail].some(value => tokenPrefixMatch(query, value))) return 320;
    if (partialPhoneMatch(query, r.phone)) return 300;
    if ([r.reason, r.meetingTitle, r.notes, r.actionItems].some(value => tokenPrefixMatch(query, value))) return 200;
    if (tokenPrefixMatch(query, r.searchIndex)) return 100;
    return 0;
  }


  function canonicalPersonName(name){
    return clean(name)
      .replace(/^(mr|mrs|ms|miss|madam|puan|encik|en|dr|dato|datuk|prof)\\.?\\s+/i, '')
      .replace(/[^a-z0-9\\s']/gi, ' ')
      .replace(/\\s+/g, ' ')
      .trim()
      .toUpperCase();
  }

  function contactIdentityKey(r){
    const personKey = canonicalPersonName(r.person);
    const companyKey = clean(r.clientShort || r.company).toUpperCase();
    if (personKey && companyKey) return personKey + '::' + companyKey;
    if (personKey) return personKey;
    return clean(r.email || r.person).toLowerCase();
  }

  function bestPersonLabel(records){
    const names = unique(records.map(r => r.person).filter(Boolean));
    if (!names.length) return 'Unnamed contact';
    return names.sort((a,b) => b.length - a.length)[0];
  }

  function fullCompanyNameForRecord(r, side){
    if (side === 'uploader') return 'Malaysian Research Accelerator for Technology & Innovation (MRANTI)';
    return clean(r.companyFull || r.company || r.clientShort || 'Unknown company');
  }

  function wrapWords(text, maxChars, maxLines){
    const words = clean(text).split(/\\s+/).filter(Boolean);
    const lines = [];
    let current = '';
    words.forEach(word => {
      const next = current ? current + ' ' + word : word;
      if (next.length > maxChars && current) {
        lines.push(current);
        current = word;
      } else {
        current = next;
      }
    });
    if (current) lines.push(current);
    if (lines.length > maxLines) {
      const kept = lines.slice(0, maxLines);
      kept[maxLines - 1] = kept[maxLines - 1].replace(/\\.*$/, '') + '…';
      return kept;
    }
    return lines;
  }

  function companyFilterKey(side, value){
    return side + '::' + clean(value).toUpperCase();
  }

  function companyMatchesFilter(r, selected){
    if (!selected) return true;
    const uploaderFull = fullCompanyNameForRecord(r, 'uploader');
    const clientFull = fullCompanyNameForRecord(r, 'client');
    return selected === companyFilterKey('uploader', uploaderFull) ||
           selected === companyFilterKey('client', clientFull);
  }

  function strengthForRecord(r){
    const keyVal = r.clientShort + '::' + canonicalPersonName(r.person);
    return records.filter(x => (x.clientShort + '::' + canonicalPersonName(x.person)) === keyVal).length;
  }

  function populateFilters(){
    const companyOptions = new Map();
    records.forEach(r => {
      const uploaderFull = fullCompanyNameForRecord(r, 'uploader');
      const clientFull = fullCompanyNameForRecord(r, 'client');
      companyOptions.set(companyFilterKey('uploader', uploaderFull), uploaderFull);
      companyOptions.set(companyFilterKey('client', clientFull), clientFull);
    });

    const cs = document.getElementById('companyFilter');
    Array.from(companyOptions.entries())
      .sort((a,b) => a[1].localeCompare(b[1]))
      .forEach(([value,label]) => {
        const o = document.createElement('option');
        o.value = value;
        o.textContent = label;
        cs.appendChild(o);
