    const candidates = records.filter(r => companyMatchesFilter(r, company) && (!uploader || r.uploader === uploader));
    if (!q) return candidates;

    const ranked = candidates
      .map(r => ({ r, score: recordSearchScore(r, q) }))
      .filter(entry => entry.score > 0)
      .sort((a,b) => b.score - a.score || new Date(b.r.timeUploaded || 0) - new Date(a.r.timeUploaded || 0));
    const bestScore = ranked[0]?.score || 0;
    const priorityFloor = bestScore >= 500 ? 500 : bestScore >= 400 ? 400 : bestScore >= 320 ? 300 : 1;
    return ranked.filter(entry => entry.score >= priorityFloor).map(entry => entry.r);
