// Generate multilingual Search Index for each newly saved CRM row.
// v15: production-safe resolver for all submission paths.
// Reads direct fields, $json.output, Map Meeting Data1, and legacy On form submission1.
// This prevents "No specific record data provided..." indexes.

function value(obj, key) {
  return String((obj && obj[key]) || '').trim();
}

function getAny(obj, keys) {
  for (const k of keys) {
    const v = value(obj, k);
    if (v) return v;
  }
  return '';
}

function safeNodeJson(nodeName) {
  try {
    return $(nodeName).item.json || {};
  } catch (e) {
    return {};
  }
}

function getGeminiKey() {
  let key = '';
  try { if (typeof $vars !== 'undefined') key = $vars.GEMINI_API_KEY || $vars.GOOGLE_GEMINI_API_KEY || ''; } catch(e) {}
  try { if (!key && typeof $env !== 'undefined') key = $env.GEMINI_API_KEY || $env.GOOGLE_GEMINI_API_KEY || ''; } catch(e) {}
  try { if (!key && typeof process !== 'undefined' && process.env) key = process.env.GEMINI_API_KEY || process.env.GOOGLE_GEMINI_API_KEY || ''; } catch(e) {}
  return String(key || '').trim();
}

const httpRequest = this?.helpers?.httpRequest
  ? this.helpers.httpRequest.bind(this.helpers)
  : null;

function cleanIndex(text) {
  return String(text || '')
    .replace(/[|]/g, ' ')
    .replace(/[`*_#]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function fallbackIndex(record) {
  return cleanIndex([
    record.companyName,
    record.personName,
    record.email,
    record.contactNumber,
    record.jobTitle,
    record.uploaderName,
    record.uploaderEmail,
    record.reason,
    record.meetingTitle,
    record.meetingDate,
    record.meetingDateOnly,
    record.meetingTime,
    record.attendees,
    record.meetingNotes,
    (record.actionItemsLegacyText || record.actionItems)
  ].join(' '));
}

function extractJsonObject(text) {
  const raw = String(text || '').trim();
  try { return JSON.parse(raw); } catch(e) {}
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) {
    try { return JSON.parse(m[0]); } catch(e) {}
  }
  return null;
}

function combineManualDateTime(dateOnly, timeOnly) {
  const d = String(dateOnly || '').trim();
  const t = String(timeOnly || '').trim();
  if (d && t) return d + ' ' + t;
  return d || t || '';
}

