  const mapMeeting = safeNodeJson('Map Meeting Data1');
  const legacyForm = safeNodeJson('On form submission1');

  const companyName =
    getAny(j, ['Company Name', 'companyName', 'company_name', 'company', 'manualCompanyName']) ||
