.page-title{font-size:30px;font-weight:900;letter-spacing:-1px}.page-sub{margin-top:7px;color:var(--muted);font-size:13px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{padding:18px;border:1px solid var(--border);border-radius:18px;background:rgba(255,255,255,.92);box-shadow:0 10px 34px rgba(37,99,235,.08)}.stat-label{color:var(--muted);font-size:10px;font-weight:800;letter-spacing:1.2px;text-transform:uppercase}.stat-value{margin-top:7px;font-size:27px;font-weight:900}.filters{display:grid;grid-template-columns:minmax(300px,1.5fr) minmax(200px,.8fr) minmax(180px,.65fr) auto;gap:12px}.filter{padding:10px 13px;border:1px solid var(--border);border-radius:15px;background:rgba(255,255,255,.92)}.filter-label{margin-bottom:5px;color:var(--muted);font-size:9px;font-weight:800;letter-spacing:1px;text-transform:uppercase}.input{width:100%;border:none;outline:none;background:transparent;color:var(--text);font-size:13px;font-weight:650}.clear{height:50px;padding:0 20px;border:1.5px solid rgba(147,197,253,.65);border-radius:14px;color:var(--blue);background:#fff;font-size:12px;font-weight:800;cursor:pointer}.directory{padding:18px;border:1px solid var(--border);border-radius:24px;background:rgba(255,255,255,.74);box-shadow:var(--shadow)}.directory-head{display:flex;justify-content:space-between;margin-bottom:15px}.directory-title{color:#1e3a5f;font-size:11px;font-weight:800;letter-spacing:1.4px;text-transform:uppercase}.result-count{color:var(--blue);font-size:11px;font-weight:800}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:13px}.card{padding:17px;border:1px solid rgba(147,197,253,.38);border-radius:18px;background:rgba(255,255,255,.96);box-shadow:0 8px 24px rgba(37,99,235,.07)}.card-head{display:flex;gap:13px}.avatar{width:48px;height:48px;flex-shrink:0;display:flex;align-items:center;justify-content:center;border-radius:16px;color:#fff;background:linear-gradient(135deg,#2563eb,#06b6d4);font-size:15px;font-weight:900}.name{font-size:14px;font-weight:900;line-height:1.35}.title{margin-top:3px;color:#475569;font-size:11.5px;font-weight:650}.badges{display:flex;flex-wrap:wrap;gap:6px;margin-top:14px}.badge{padding:5px 8px;border-radius:999px;font-size:9.5px;font-weight:800}.department{color:#1e40af;background:#eff6ff;border:1px solid #bfdbfe}.active{color:#047857;background:#ecfdf5;border:1px solid #a7f3d0}.suspended{color:#b45309;background:#fffbeb;border:1px solid #fde68a}.archived{color:#475569;background:#f1f5f9;border:1px solid #cbd5e1}.admin{color:#6d28d9;background:#f5f3ff;border:1px solid #ddd6fe}.details{display:flex;flex-direction:column;gap:7px;margin-top:15px;padding-top:13px;border-top:1px solid #e2e8f0}.row{display:grid;grid-template-columns:76px 1fr;gap:9px;font-size:10.5px;line-height:1.4}.label{color:var(--muted2);font-weight:750}.value{min-width:0;color:#334155;font-weight:650;word-break:break-word}.email{color:var(--blue);text-decoration:none}.empty{display:none;padding:70px 25px;text-align:center;color:var(--muted)}
