<body><div class="shell">
<header class="top-nav"><div class="brand"><div class="logo"></div><div class="divider"></div><div><div class="kicker">MRANTI Workspace</div><div class="brand-sub">Internal people and organisation directory</div></div></div><div class="actions"><a class="nav" href="${contactsUrl}">CRM Contacts</a><a class="nav" href="${graphUrl}">Relationship Graph</a><a class="back" href="${homeUrl}">Back to Home</a></div></header>
<section><h1 class="page-title">MRANTI Staff Directory</h1><p class="page-sub">Find MRANTI colleagues by name, department, job title, organisation unit, email or phone.</p></section>
<section class="stats"><div class="stat"><div class="stat-label">Directory Accounts</div><div class="stat-value">${totalUsers}</div></div><div class="stat"><div class="stat-label">Active Staff</div><div class="stat-value">${activeUsers}</div></div><div class="stat"><div class="stat-label">Departments</div><div class="stat-value">${departments}</div></div><div class="stat"><div class="stat-label">Administrators</div><div class="stat-value">${adminUsers}</div></div></section>
<section class="filters"><div class="filter"><div class="filter-label">Search staff</div><input id="searchInput" class="input" placeholder="Search name, email, role, department or phone..." oninput="render()"/></div><div class="filter"><div class="filter-label">Department</div><select id="departmentFilter" class="input" onchange="render()"><option value="">All Departments</option></select></div><div class="filter"><div class="filter-label">Account Status</div><select id="statusFilter" class="input" onchange="render()"><option value="Active" selected>Active Staff</option><option value="">All Accounts</option><option value="Suspended">Suspended</option><option value="Archived">Archived</option></select></div><button class="clear" onclick="resetFilters()">Clear Filters</button></section>
<main class="directory"><div class="directory-head"><div class="directory-title">Staff Members</div><div class="result-count" id="resultCount"></div></div><div class="grid" id="staffGrid"></div><div class="empty" id="emptyState">No staff members matched the selected filters.</div></main>
</div>
<script>
const users=${usersJson};
function esc(v){return String(v||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}
function norm(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/&/g,' and ').replace(/[^a-z0-9\\s@._+/-]/g,' ').replace(/\\s+/g,' ').trim()}
function initials(n){const p=String(n||'').trim().split(/\\s+/).filter(Boolean);return !p.length?'MR':p.length===1?p[0].slice(0,2).toUpperCase():(p[0][0]+p[p.length-1][0]).toUpperCase()}
function searchText(u){return norm([u.fullName,u.givenName,u.familyName,u.primaryEmail,u.jobTitle,u.department,u.organisationName,u.organisationUnit,u.location,u.phoneNumbers,u.aliases,u.status].join(' '))}
function populate(){const vals=[...new Set(users.map(u=>u.department).filter(Boolean))].sort((a,b)=>a.localeCompare(b));const s=document.getElementById('departmentFilter');vals.forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;s.appendChild(o)})}
function badgeStatus(s){return s==='Suspended'?'suspended':s==='Archived'?'archived':'active'}
function staffCard(u){const d=u.department?'<span class="badge department">'+esc(u.department)+'</span>':'';const a=(u.isAdmin||u.isDelegatedAdmin)?'<span class="badge admin">Administrator</span>':'';const phone=u.phoneNumbers?'<div class="row"><div class="label">Phone</div><div class="value">'+esc(u.phoneNumbers)+'</div></div>':'';const unit=u.organisationUnit?'<div class="row"><div class="label">Org Unit</div><div class="value">'+esc(u.organisationUnit)+'</div></div>':'';const location=u.location?'<div class="row"><div class="label">Location</div><div class="value">'+esc(u.location)+'</div></div>':'';return '<article class="card"><div class="card-head"><div class="avatar">'+esc(initials(u.fullName))+'</div><div><div class="name">'+esc(u.fullName||'Unnamed staff')+'</div><div class="title">'+esc(u.jobTitle||u.department||'MRANTI Staff')+'</div></div></div><div class="badges">'+d+'<span class="badge '+badgeStatus(u.status)+'">'+esc(u.status)+'</span>'+a+'</div><div class="details"><div class="row"><div class="label">Email</div><div class="value"><a class="email" href="mailto:'+esc(u.primaryEmail)+'">'+esc(u.primaryEmail||'No email')+'</a></div></div>'+unit+location+phone+'</div></article>'}
function render(){const q=norm(document.getElementById('searchInput').value);const dep=document.getElementById('departmentFilter').value;const status=document.getElementById('statusFilter').value;const filtered=users.filter(u=>(!dep||u.department===dep)&&(!status||u.status===status)&&(!q||searchText(u).includes(q)));document.getElementById('resultCount').textContent=filtered.length+(filtered.length===1?' staff member':' staff members');document.getElementById('staffGrid').innerHTML=filtered.map(staffCard).join('');document.getElementById('emptyState').style.display=filtered.length?'none':'block'}
function resetFilters(){document.getElementById('searchInput').value='';document.getElementById('departmentFilter').value='';document.getElementById('statusFilter').value='Active';render()}
populate();render();
</script></body></html>`;
return [{json:{html}}];

const source = $('Map Meeting Data1').first();
const sourceJson = source?.json || {};
const sourceBinary = source?.binary || {};
const prepared = $('Prepare Meeting PDF Uploads').all();
const uploaded = $input.all();

const calendarAttachments = (Array.isArray(sourceJson.calendarAttachments) ? sourceJson.calendarAttachments : [])
  .map((entry, index) => ({
    name: String(entry?.name || `Calendar attachment ${index + 1}`).trim(),
    url: String(entry?.url || '').trim(),
    mimeType: String(entry?.mimeType || '').trim(),
    source: 'calendar'
  }))
  .filter(entry => entry.url);

const uploadedDocuments = [];
const failedNames = [];

for (let i = 0; i < prepared.length; i++) {
  const meta = prepared[i]?.json || {};
  const result = uploaded[i]?.json || {};
  const originalName = String(meta.originalName || `Meeting document ${i + 1}`);
  const fileId = String(result.id || result.fileId || '').trim();
  const explicitError = result.error || result.message || '';

  if (fileId && !explicitError) {
    uploadedDocuments.push({
      name: originalName,
      url: result.webViewLink || `https://drive.google.com/file/d/${fileId}/view`,
      id: fileId,
      source: 'uploaded'
    });
  } else {
    failedNames.push(originalName);
  }
}

const seen = new Set();
const documents = [...calendarAttachments, ...uploadedDocuments].filter(document => {
  const key = `${document.url}::${document.name}`;
  if (!document.url || seen.has(key)) return false;
  seen.add(key);
  return true;
});

const meetingDocumentsCell = documents
  .map(document => `${document.source === 'calendar' ? 'Calendar' : 'Uploaded'} | ${document.name} | ${document.url}`)
  .join('\n');

return [{
  json: {
    ...sourceJson,
    calendarAttachments,
    calendarAttachmentCount: calendarAttachments.length,
    meetingDocuments: documents,
    meetingDocumentsCell,
    meetingDocumentsUploadedCount: uploadedDocuments.length,
    meetingDocumentsFailedCount: failedNames.length,
    meetingDocumentsFailedNames: failedNames
  },
  binary: sourceBinary
}];

return items.map((item) => {
  const binary = { ...(item.binary || {}) };

  for (const key of Object.keys(binary)) {
    if (key === 'meetingDocument' || /^meetingDocument_\d+$/i.test(key)) {
      delete binary[key];
    }
  }

  const json = item.json || {};
  const rawDocuments = Array.isArray(json.meetingDocuments) ? json.meetingDocuments : [];
  const seen = new Set();
  const documents = rawDocuments
    .map((document, index) => ({
      name: String(document?.name || `Meeting document ${index + 1}`).trim(),
      url: String(document?.url || '').trim(),
      mimeType: String(document?.mimeType || '').trim(),
      source: document?.source === 'calendar' ? 'calendar' : 'uploaded',
      id: String(document?.id || '').trim()
    }))
    .filter(document => {
      const key = `${document.url}::${document.name}`;
      if (!document.url || seen.has(key)) return false;
      seen.add(key);
      return true;
    });

  const calendarAttachments = documents.filter(document => document.source === 'calendar');
  const meetingDocumentsCell = documents
    .map(document => `${document.source === 'calendar' ? 'Calendar' : 'Uploaded'} | ${document.name} | ${document.url}`)
    .join('\n');
  const failedNames = Array.isArray(json.meetingDocumentsFailedNames) ? json.meetingDocumentsFailedNames : [];

  return {
    json: {
      ...json,
      calendarAttachments,
      calendarAttachmentCount: calendarAttachments.length,
      meetingDocuments: documents,
      meetingDocumentsCell,
      meetingDocumentsUploadedCount: Number(json.meetingDocumentsUploadedCount || 0),
      meetingDocumentsFailedCount: Number(json.meetingDocumentsFailedCount || 0),
      meetingDocumentsFailedNames: failedNames
    },
    binary
  };
});

const source = $input.first();
const sourceJson = source.json || {};
const sourceBinary = source.binary || {};
const keys = Array.isArray(sourceJson.meetingDocumentBinaryKeys)
  ? sourceJson.meetingDocumentBinaryKeys.slice(0, 5)
  : Object.keys(sourceBinary)
      .filter(key => key === 'meetingDocument' || /^meetingDocument_\d+$/i.test(key))
      .slice(0, 5);

return keys.map((key, index) => {
  const file = sourceBinary[key] || {};
  const originalName = String(file.fileName || `meeting-document-${index + 1}.pdf`);
  const safeName = originalName
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '') || `meeting-document-${index + 1}.pdf`;
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');

  return {
    json: {
      documentIndex: index,
      originalName,
      storedName: `MRANTI-CRM_${stamp}_${index + 1}_${safeName}`
    },
    binary: {
      meetingDocument: file
    }
  };
});

const binary = $binary || {};
const key = binary.businessCard ? 'businessCard' : Object.keys(binary)[0];
const file = key ? binary[key] : null;
const mimeType = String(file?.mimeType || '').toLowerCase();
const fileName = String(file?.fileName || $json.body?.fileName || 'business-cards');
const fileSize = Number(file?.fileSize || 0);
const supported = Boolean(file) && (mimeType.startsWith('image/') || mimeType === 'application/pdf' || /\.pdf$/i.test(fileName));
const withinLimit = !fileSize || fileSize <= 20 * 1024 * 1024;

return [{
  json: {
    hasBusinessCard: supported && withinLimit ? 'yes' : 'no',
    errorMessage: !file
      ? 'No business-card image was received.'
      : !supported
        ? 'The uploaded file must be an image or PDF.'
        : !withinLimit
          ? 'The uploaded business-card file is larger than 20 MB.'
          : '',
    originalFileName: fileName
  },
  binary: file ? { businessCard: file } : {}
}];

function extractText(value) {
  return (value?.content?.parts || []).map(part => part?.text || '').join('\n').trim();
}

function parseJson(text) {
  const raw = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  try { return JSON.parse(raw); } catch (e) {}
  const objectMatch = raw.match(/\{[\s\S]*\}/);
  if (objectMatch) {
    try { return JSON.parse(objectMatch[0]); } catch (e) {}
  }
  const arrayMatch = raw.match(/\[[\s\S]*\]/);
  if (arrayMatch) {
    try { return { contacts: JSON.parse(arrayMatch[0]) }; } catch (e) {}
  }
  return null;
}

function normalize(entry, index) {
  const email = String(entry?.email || entry?.emailAddress || entry?.['Email Address'] || '').trim();
  const contactNumber = String(entry?.contactNumber || entry?.phone || entry?.mobile || entry?.['Contact Number'] || '').trim();
  const personName = String(entry?.personName || entry?.name || entry?.['Person Name'] || '').trim();
  const companyName = String(entry?.companyName || entry?.company || entry?.['Company Name'] || '').trim();
  const jobTitle = String(entry?.jobTitle || entry?.designation || entry?.title || '').trim();
  const reviewReasons = Array.isArray(entry?.reviewReasons)
    ? entry.reviewReasons.map(value => String(value || '').trim()).filter(Boolean)
    : [];

  if (!personName && !reviewReasons.includes('Person name is unclear or missing')) reviewReasons.push('Person name is unclear or missing');
  if (!companyName && !reviewReasons.includes('Company name is unclear or missing')) reviewReasons.push('Company name is unclear or missing');
  if (!email && !contactNumber && !reviewReasons.includes('Email and contact number are unclear or missing')) reviewReasons.push('Email and contact number are unclear or missing');

  return {
    cardNumber: index + 1,
    personName,
    companyName,
    email,
    contactNumber,
    jobTitle,
    confidence: String(entry?.confidence || (reviewReasons.length ? 'low' : 'medium')).toLowerCase(),
    reviewReasons
  };
}

const text = extractText($json);
const parsed = parseJson(text);
const rawContacts = Array.isArray(parsed) ? parsed : Array.isArray(parsed?.contacts) ? parsed.contacts : [];
const contacts = [];
const seen = new Set();

for (const entry of rawContacts.slice(0, 10)) {
  const contact = normalize(entry, contacts.length);
  if (![contact.personName, contact.companyName, contact.email, contact.contactNumber].some(Boolean)) continue;
  const key = [contact.email.toLowerCase(), contact.personName.toLowerCase(), contact.companyName.toLowerCase(), contact.contactNumber.toLowerCase()].join('|');
  if (seen.has(key)) continue;
  seen.add(key);
  contacts.push(contact);
}

if (!contacts.length) {
  return [{ json: { success: false, detectedCardCount: 0, contacts: [], error: 'No distinct business card could be detected. Use a sharper photo with every card fully visible.' } }];
}

const reviewRequired = contacts.filter(contact => contact.reviewReasons.length > 0).length;
return [{
  json: {
    success: true,
    detectedCardCount: contacts.length,
    reviewRequired,
    contacts
  }
}];

const source = $input.first();
const sourceJson = source?.json || {};
const raw = Array.isArray(sourceJson.reviewedContacts) ? sourceJson.reviewedContacts.slice(0, 10) : [];
if (!raw.length) throw new Error('No reviewed contacts were received.');
function key(value){return String(value||'').toLowerCase().trim().replace(/[^a-z0-9@]+/g,' ').replace(/\s+/g,' ').trim();}
function cleanAttendees(value, organisation){const blocked=key(organisation);const seen=new Set();return String(value||'').split(/\r?\n|;|,/).map(v=>v.trim()).filter(v=>{const k=key(v);if(!k||k===blocked||seen.has(k))return false;seen.add(k);return true;}).join(', ');}
const contacts = []; const seen = new Set();
for (let index = 0; index < raw.length; index++) {
  const entry = raw[index] || {};
  const personName = String(entry.personName || '').trim(); const companyName = String(entry.companyName || '').trim();
  const email = String(entry.email || '').trim(); const contactNumber = String(entry.contactNumber || '').trim(); const jobTitle = String(entry.jobTitle || '').trim();
  if (!personName) throw new Error(`Contact ${index + 1}: person name is required.`);
  if (!companyName) throw new Error(`Contact ${index + 1}: company name is required.`);
  if (!email && !contactNumber) throw new Error(`Contact ${index + 1}: email or contact number is required.`);
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error(`Contact ${index + 1}: email format is invalid.`);
  const dedupe=[email.toLowerCase(),personName.toLowerCase(),companyName.toLowerCase(),contactNumber.toLowerCase()].join('|');
  if(seen.has(dedupe))continue;seen.add(dedupe);contacts.push({personName,companyName,email,contactNumber,jobTitle});
}
if (!contacts.length) throw new Error('All reviewed contacts were duplicates or empty.');
return contacts.map((contact,index)=>({json:{
  ...sourceJson, attendees:cleanAttendees(sourceJson.attendees,contact.companyName), reviewedContactIndex:index, reviewedContactCount:contacts.length,
  recordId:`${sourceJson.submissionId || ('CRM-' + Date.now().toString(36).toUpperCase())}-${String(index+1).padStart(2,'0')}`,
  recordStatus:'Active',lastUpdated:sourceJson.submittedAt||new Date().toISOString(),updatedBy:sourceJson.uploaderEmail||'',
  output:{'Company Name':contact.companyName,'Person Name':contact.personName,'Email Address':contact.email,'Contact Number':contact.contactNumber,'Job Title':contact.jobTitle}
}}));

// Generate multilingual Search Index for each newly saved CRM row.
// v15: production-safe resolver for all submission paths.
// Reads direct fields, $json.output, Map Meeting Data1, and legacy On form submission1.
// This prevents "No specific record data provided..." indexes.

function value(obj, key) {
  return String((obj && obj[key]) || '').trim();
}

function getAny(obj, keys) {
  for (const k of keys) {
    const v = value(obj, k);
    if (v) return v;
  }
  return '';
}

function safeNodeJson(nodeName) {
  try {
    return $(nodeName).item.json || {};
  } catch (e) {
    return {};
  }
}

function getGeminiKey() {
  let key = '';
  try { if (typeof $vars !== 'undefined') key = $vars.GEMINI_API_KEY || $vars.GOOGLE_GEMINI_API_KEY || ''; } catch(e) {}
  try { if (!key && typeof $env !== 'undefined') key = $env.GEMINI_API_KEY || $env.GOOGLE_GEMINI_API_KEY || ''; } catch(e) {}
  try { if (!key && typeof process !== 'undefined' && process.env) key = process.env.GEMINI_API_KEY || process.env.GOOGLE_GEMINI_API_KEY || ''; } catch(e) {}
  return String(key || '').trim();
}

const httpRequest = this?.helpers?.httpRequest
  ? this.helpers.httpRequest.bind(this.helpers)
  : null;

function cleanIndex(text) {
  return String(text || '')
    .replace(/[|]/g, ' ')
    .replace(/[`*_#]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function fallbackIndex(record) {
  return cleanIndex([
    record.companyName,
    record.personName,
    record.email,
    record.contactNumber,
    record.jobTitle,
    record.uploaderName,
    record.uploaderEmail,
    record.reason,
    record.meetingTitle,
    record.meetingDate,
    record.meetingDateOnly,
    record.meetingTime,
    record.attendees,
    record.meetingNotes,
    (record.actionItemsLegacyText || record.actionItems)
  ].join(' '));
}

function extractJsonObject(text) {
  const raw = String(text || '').trim();
  try { return JSON.parse(raw); } catch(e) {}
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) {
    try { return JSON.parse(m[0]); } catch(e) {}
  }
  return null;
}

function combineManualDateTime(dateOnly, timeOnly) {
  const d = String(dateOnly || '').trim();
  const t = String(timeOnly || '').trim();
  if (d && t) return d + ' ' + t;
  return d || t || '';
}

function buildRecordFromItem(itemJson) {
  const j = itemJson || {};
  const output = j.output || {};

  const mapMeeting = safeNodeJson('Map Meeting Data1');
  const legacyForm = safeNodeJson('On form submission1');

