async function callGemini(record) {
  const base = fallbackIndex(record);
  const key = getGeminiKey();

  if (!base) {
    return {
      ok: false,
      source: 'fallback_empty_record',
      error: 'No CRM fields were resolved before Search Index generation.',
      searchIndex: ''
    };
  }

  if (!key) {
    return {
      ok: false,
      source: 'fallback_no_gemini_key',
      error: 'GEMINI_API_KEY not available to Code node.',
      searchIndex: base
    };
  }

  if (!httpRequest) {
    return {
      ok: false,
      source: 'fallback_no_http_helper',
      error: 'n8n HTTP helper is not available in this Code node.',
      searchIndex: base
    };
  }

  const prompt = `
You are building a hidden multilingual search index for a CRM record.

TASK:
Generate a bilingual Bahasa Malaysia + English search index so users can search in either language and still find this CRM record.

ABSOLUTE REQUIREMENTS:
1. Include the original company name exactly.
2. Include likely official Bahasa Malaysia equivalent if the original is English.
3. Include likely English equivalent if the original is Bahasa Malaysia.
4. Include meaningful terms from BOTH languages.
5. Include common abbreviation only if clearly inferable from name/email/domain/context.
6. Include meeting topic synonyms in BM and English.
7. Do not invent unrelated organisations or people.
8. Return JSON only.

EXAMPLES:
- "Ministry of Science, Technology and Innovation" must include:
  "Kementerian Sains Teknologi dan Inovasi", "sains", "science", "teknologi", "technology", "inovasi", "innovation", "MOSTI" if inferable.
- "Ministry of Economy" must include:
  "Kementerian Ekonomi", "ekonomi", "economy", "dasar", "policy", "perancangan", "planning" if relevant.
- "Malaysian Technology Development Corporation" must include:
  "MTDC", "Perbadanan Pembangunan Teknologi Malaysia", "teknologi", "technology", "pembangunan", "development" if relevant.
- "Suruhanjaya Sekuriti (Securities Commission Malaysia)" must include both Malay and English forms.

Record:
Company Name: ${record.companyName}
Person Name: ${record.personName}
Email: ${record.email}
Contact Number: ${record.contactNumber}
Uploader: ${record.uploaderName}
Uploader Email: ${record.uploaderEmail}
Reason: ${record.reason}
Meeting Title: ${record.meetingTitle}
Meeting Date: ${record.meetingDate}
Meeting Date Only: ${record.meetingDateOnly}
Meeting Time: ${record.meetingTime}
Attendees: ${record.attendees}
Meeting Notes: ${record.meetingNotes}
Action Items: ${record.actionItems}
Job Title: ${record.jobTitle}

Return strict JSON:
{
  "search_index": "single compact plain-text string under 180 words",
  "language_coverage": "bilingual|mostly_english|mostly_bm|unknown",
  "abbreviations": ["..."],
  "confidence": "high|medium|low"
}
`;

  const models = ['gemini-2.5-flash', 'gemini-2.0-flash', 'gemini-1.5-flash'];
  let lastError = '';

  for (const model of models) {
    try {
      const data = await httpRequest({
        method: 'POST',
        url: 'https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent?key=' + encodeURIComponent(key),
        headers: { 'Content-Type': 'application/json' },
        body: {
          contents: [{ role: 'user', parts: [{ text: prompt }] }],
          generationConfig: {
            temperature: 0.1,
            responseMimeType: 'application/json'
          }
        },
        json: true,
        timeout: 60000
      });

      const text = (data.candidates?.[0]?.content?.parts || [])
        .map(p => p.text || '')
        .join(' ')
        .trim();

      const parsed = extractJsonObject(text);

      if (!parsed || !parsed.search_index) {
        lastError = model + ': Gemini returned invalid JSON/search_index.';
        continue;
      }

      const generated = cleanIndex(parsed.search_index);
      const combined = cleanIndex(base + ' ' + generated + ' ' + (parsed.abbreviations || []).join(' '));

      return {
        ok: true,
        source: 'gemini_http_' + model,
        error: '',
        searchIndex: combined,
        languageCoverage: parsed.language_coverage || 'unknown',
        confidence: parsed.confidence || 'unknown'
      };

    } catch (e) {
      lastError = model + ': ' + (e.message || String(e));
    }
  }

  return {
    ok: false,
    source: 'fallback_gemini_error',
    error: lastError || 'Gemini HTTP request failed.',
    searchIndex: base
  };
}

const out = [];

